const Management={types:{structure:'库存结构统计',outbound:'正式出库统计',fulfilment:'销售计划履约统计',loading:'装车计划执行统计',differences:'盘点差异统计'},sequence:0,
 tone(v){return /REJECTED|已驳回|RECTIFY|待整改/.test(v)?'rejected':/CANCELLED|REVERSED|已取消|已冲销/.test(v)?'muted':/PENDING|REVIEW|APPROVAL|WAITING|MATCHED|LOADING|OPEN|待|作业中|执行中/.test(v)?'attention':'';},
 label(k){return I18n.translate(ManagementLabels.columns[k]||k,true);},value(k,v){if(v==null)return /weight|_net$/.test(k)?'未知':'—';if(v==='')return '—';if(/weight|_net$/.test(k))return Tonnes.format(v);if(k==='finding')return V27Counts.findings[v]||ManagementLabels.text(v,false);if(k==='code')return V27Reliability.findingName(v);return ManagementLabels.names[v]||V27Counts.phases[v]||V26.states[v]||({WORKING:'作业中',RECTIFY:'待整改',ANNUAL:'年度盘点',MONTHLY:'月度盘点',SPECIAL:'专项盘点',DRAFT:'草稿',CONFIRMED:'已确认',CLOSED:'已关闭'})[v]||Control.names[v]||ManagementLabels.text(v,false);},
 query(q){return new URLSearchParams(Object.entries(q).filter(([k,v])=>v!==undefined&&v!==null&&(v!==''||k==='dimension')));},
 link(kind,extra={},source='overview'){const path=({inventory:'/inventory',outbound:'/outbounds',loading:'/loading-plans',todos:'/overview',alerts:'/overview'})[kind];return path+'?'+this.query({...Dashboard.filters,management:kind,source,...extra});},
 table(rows,columns,managed=true,headings={}){return `<div class="business-table v34-table-wrap"><table ${managed?'data-v34-server="true"':''}><thead><tr>${columns.map(k=>`<th>${managed?`<button class="v34-sort" data-v34-sort="${esc(k)}">${esc(I18n.translate(headings[k]||this.label(k),true))}<span aria-hidden="true"> ↕</span></button>`:esc(I18n.translate(headings[k]||this.label(k),true))}</th>`).join('')}<th>${I18n.translate('操作',true)}</th></tr></thead><tbody>${rows.map(r=>`<tr>${columns.map(k=>`<td ${['customer_name','bundle_no','lot_no','location','vehicle_no','contract_no','document_no','task_code','code','packing_list_no','loading_plan_no','invoice_no','shipment_batch_no'].includes(k)?'data-no-i18n':''}>${r.links?.[k]?`<a data-no-i18n href="${esc(r.links[k])}">${esc(this.value(k,r[k]))}</a>`:k==='location'&&r.location_href?`<a data-no-i18n href="${esc(r.location_href)}">${esc(r[k])}</a>`:['status','inventory_state','finding','type','kind'].includes(k)?`<span class="v34-state ${this.tone(r[k])}">${esc(this.value(k,r[k]))}</span>`:esc(this.value(k,r[k]))}</td>`).join('')}<td>${r.actions?r.actions.map(a=>`<a class="button secondary compact" href="${esc(a.href)}">${esc(I18n.translate(a.label,true))}</a>`).join(' '):r.href?`<a class="button secondary compact" href="${esc(r.href)}">${I18n.language==='en'?'View Details':'查看详情'}</a>`:r.drill?`<a class="button secondary compact" href="${esc(r.drill)}">${I18n.language==='en'?'View Detail':'明细钻取'}</a>`:'—'}</td></tr>`).join('')||`<tr><td colspan="${columns.length+1}" class="empty">${I18n.language==='en'?'No Matching Records':'当前条件无记录'}</td></tr>`}</tbody></table></div>`;},
 pager(r){return `<div class="v34-pagination"><span><span>${I18n.language==='en'?'Total':'共'}</span> ${r.total} <span>${I18n.language==='en'?'records':'条'}</span></span><label>${I18n.language==='en'?'Per page':'每页'}<select id="v34-page-size">${[10,25,50,100].map(n=>`<option value="${n}" ${n===r.page_size?'selected':''}>${n}</option>`).join('')}</select></label><button id="v34-prev" class="button secondary" ${r.page===1?'disabled':''}>${I18n.language==='en'?'Previous':'上一页'}</button><span>${r.page} / ${Math.max(1,Math.ceil(r.total/r.page_size))}</span><button id="v34-next" class="button secondary" ${r.page*r.page_size>=r.total?'disabled':''}>${I18n.language==='en'?'Next':'下一页'}</button></div>`;},
 bindPaging(r,run){const q=new URLSearchParams(location.search);for(const [id,delta] of [['v34-prev',-1],['v34-next',1]])$(id).onclick=()=>{q.set('page',r.page+delta);run(q);};$('v34-page-size').onchange=e=>{q.set('page_size',e.target.value);q.set('page',1);run(q);};for(const b of document.querySelectorAll('[data-v34-sort]'))b.onclick=()=>{q.set('sort',b.dataset.v34Sort);q.set('direction',r.sort===b.dataset.v34Sort&&r.direction==='asc'?'desc':'asc');q.set('page',1);run(q);};},
 async refresh(){const seq=++this.sequence;try{const r=await API.request('/v34/overview?'+this.query(Dashboard.filters));if(seq!==this.sequence||!window.AppSignedIn)return;Dashboard.snapshot=r;$('dashboard-error').textContent='';const card=(label,value,unit,kind,extra={})=>`<a class="v34-kpi" href="${esc(this.link(kind,extra))}"><span>${label}</span><strong>${esc(value)}<small>${unit}</small></strong><span class="v34-card-arrow" aria-hidden="true">↗</span></a>`,inv=r.metrics,out=r.outbound,unknown=inv.physical.unknown_weights;
 $('dashboard-content').innerHTML=`<p class="overview-scope"><span>统计期间</span> <strong data-no-i18n>${esc(r.window.from)} — ${esc(r.window.to)}</strong> · <span>实时读取业务数据库</span></p><section class="v34-overview-section"><h2>库存概览</h2><div class="v34-kpi-grid">${[['实物库存净重','physical',''],['可用库存净重','available','AVAILABLE'],['已备货锁定净重','locked','PREPARATION_LOCKED'],['已装车待正式出库净重','loaded','LOADED_PENDING']].map(([label,key,state])=>card(label,Tonnes.format(inv[key].net_weight),'吨','inventory',{state})).join('')}</div><p class="v34-definition">实物库存包含未正式出库的全部业务状态，每捆仅计一次；已分配装车单独列示，不重复计入备货锁定。</p><p><a href="${esc(this.link('inventory',{state:'LOADING_ASSIGNED'}))}"><span>已分配装车净重</span>：${Tonnes.format(inv.assigned.net_weight)} <span>吨</span></a>${unknown?` · <span>重量未知捆数</span>：${unknown}`:''}</p></section><section class="v34-overview-section"><h2>出库统计</h2><div class="v34-kpi-grid">${card('本期正式出库车辆数',out.vehicles,'辆','outbound')}${card('本期正式出库净重',Tonnes.format(out.net_weight),'吨','outbound')}${card('累计正式出库净重',Tonnes.format(out.cumulative_net_weight),'吨','outbound',{cumulative:1})}</div><p class="v34-definition">默认显示本月；按生产经理最终审批时间统计，排除已生效返场冲销。车辆离场不提前计入。</p></section><section class="v34-overview-section"><h2>装车计划统计</h2><p class="v34-definition">装车计划按当前全部有效任务分类；报表可另按计划日期筛选。</p><div class="v34-kpi-grid compact-grid">${Object.entries(r.loading_plans).map(([state,n])=>card(ManagementLabels.names[state],n,'张','loading',{state})).join('')}</div></section><section class="v34-overview-section"><div class="v34-section-heading"><h2>客户库存统计</h2><span>当前分配客户优先，未分配按货权客户归集</span></div>${this.table(r.customers.map(c=>({...c,physical_net_weight:c.net_weight,links:{bundles:this.link('inventory',{customer:c.customer_id}),physical_net_weight:this.link('inventory',{customer:c.customer_id}),prepared_bundles:this.link('inventory',{customer:c.customer_id,prepared:1}),outbound_bundles:this.link('outbound',{customer:c.customer_id,cumulative:1})},href:this.link('inventory',{customer:c.customer_id})})),['customer_name','bundles','physical_net_weight','prepared_bundles','outbound_bundles'],false)}</section><div class="v34-overview-split"><section class="v34-overview-section v34-attention ${r.todos.length?'has-items':''}"><div class="v34-section-heading"><h2><span>我的待办</span><strong class="attention-count" data-no-i18n>${r.todos.length}</strong></h2><a href="${esc(this.link('todos'))}"><span>查看全部</span> (${r.todos.length})</a></div>${r.todos.slice(0,6).map(t=>`<a class="v34-task" href="${esc(t.href)}"><span>${esc(ManagementLabels.names[t.kind]||t.kind)}</span><strong data-no-i18n>${esc(t.document_no)}</strong><span aria-hidden="true">→</span></a>`).join('')||'<p class="empty">当前没有可执行待办</p>'}<p class="v34-definition">仅显示当前权限可执行的任务，沿用原有独立审批要求。</p></section><section class="v34-overview-section v34-attention warning-center ${r.alerts.length?'has-items':''}"><div class="v34-section-heading"><h2><span>异常预警</span><strong class="attention-count" data-no-i18n>${r.alerts.length}</strong></h2><a href="${esc(this.link('alerts'))}"><span>查看全部</span> (${r.alerts.length})</a></div>${r.alerts.slice(0,6).map(a=>`<a class="v34-task warning" href="${esc(a.href)}"><span>${esc(ManagementLabels.names[a.type]||a.type)}</span><strong data-no-i18n>${esc(a.document_no)}</strong><span aria-hidden="true">→</span></a>`).join('')||'<p class="empty">当前无异常预警</p>'}<p class="v34-definition">预警实时计算，条件消失后自动恢复，不修改业务单据。</p>${Business.can('system:manage')?'<a class="button secondary compact" href="/overview/warning-settings">预警阈值设置</a>':''}</section></div>`;I18n.apply();
 }catch(e){if(seq===this.sequence){$('dashboard-error').textContent=e.message;$('dashboard-content').replaceChildren();}}},
 async drill(){const q=new URLSearchParams(location.search),kind=q.get('management'),r=await API.request('/v34/details?'+this.query({...Object.fromEntries(q),kind})),titles={inventory:'库存明细',outbound:'正式出库明细',loading:'装车计划单（Loading Plan）',todos:'我的待办',alerts:'异常预警'},columns=({inventory:['bundle_no','customer_name','lot_no','location','inventory_state','net_weight'],outbound:['document_no','vehicle_no','customer_name','contract_no','date','bundles','net_weight'],loading:['document_no','customer_name','planned_date','status'],todos:['kind','document_no','status','created_at'],alerts:['type','document_no','bundle_no','finding','hours','days']})[kind];Router.page(titles[kind],`<p>来自同一统计口径的实时授权明细</p><div class="business-toolbar"><a class="button secondary" href="/overview">返回信息总览</a><a class="button secondary" href="${esc(location.pathname)}">清除统计筛选</a></div>${this.table(r.items,columns)}${this.pager(r)}`);this.bindPaging(r,q=>Router.go(location.pathname+'?'+q));I18n.apply();},
 reportDrill(type,q,group,value,customer){const p=this.query({...Object.fromEntries(q),management:type==='structure'?'inventory':'outbound',source:'report',group_by:group,...(group==='customer_name'?{customer}:{}),sort:undefined,page:1});p.set('dimension',String(value??''));return (type==='structure'?'/inventory':'/outbounds')+'?'+p;},
 async reports(){return Reports463.render();},
 async warningSettings(){const rows=await API.request('/v34/warning-settings');Router.page('预警阈值设置',`<p>装车超期小时沿用现有异常规则。其他阈值为允许超过的天数或小时；0表示达到条件立即提示。</p><form id="v34-warning-settings" class="user-form"><label>项目<select name="project_id">${rows.map(r=>`<option value="${r.project_id}">${esc(r.project_name)}</option>`).join('')}</select></label><div class="form-grid"><label>计划日期宽限天数<input name="plan_overdue_days" type="number" min="0" max="3650" required></label><label>已装车未正式出库小时<input name="loaded_hours" type="number" min="0.001" max="87600" step="0.001" required></label><label>正式出库后单证宽限小时<input name="document_hours" type="number" min="0" max="87600" required></label><label>未完成盘点差异宽限天数<input name="count_difference_days" type="number" min="0" max="3650" required></label></div><p id="v34-settings-error" class="error" role="alert"></p><button class="button primary">保存预警设置</button></form>`);const f=$('v34-warning-settings'),fill=()=>{const r=rows.find(r=>r.project_id===f.elements.project_id.value);for(const k of ['plan_overdue_days','loaded_hours','document_hours','count_difference_days'])f.elements[k].value=r[k];};f.elements.project_id.onchange=fill;fill();f.onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const b=Object.fromEntries(new FormData(f)),r=rows.find(r=>r.project_id===b.project_id);for(const k of ['plan_overdue_days','document_hours','count_difference_days'])b[k]=Number(b[k]);await API.request('/v34/warning-settings',{method:'PATCH',body:{...b,version:r.version}});await this.warningSettings();}catch(err){$('v34-settings-error').textContent=err.message;e.submitter.disabled=false;}};I18n.apply();}
};
