 const items=r.items.map(row=>{const actions=[{label:'查看详情',href:row.href}];if(kind==='plans'){if(Business.can('plan:write'))actions.push({label:'编辑',href:'/sales-plans/'+row.id+'/edit'});if(Business.can('dispatch:read'))actions.push({label:'派车管理',href:'/sales-plans/'+row.id+'/dispatch'});}if(kind==='loading'){const base=row.entry_type==='DRAFT'?'/loading-plans/'+row.id:'/loading-plans/orders/'+row.id;actions[0].href=base;if(Business.can('loading-plan:write')&&!['COMPLETED','CANCELLED'].includes(row.state))actions.push({label:'编辑',href:base+'/edit'},{label:'取消',href:base+'/cancel'});if(row.state==='WAITING'&&Business.can('load:write')&&Business.can('loading-plan:match'))actions.push({label:'创建装车单',href:'/outbounds/loads/new?document_id='+row.id});}return {...row,...(kind==='plans'?{status:row.status==='OPEN'?'执行中':row.status==='CLOSED'?'已完成':row.status}:{}),actions};});
